{
  "root_cause": "DialogBase does not manage focus when opening or closing dialogs/drawers. When a drawer opens via keyboard, focus remains on the triggering element or body, preventing keyboard users from interacting with the drawer's controls. When the drawer closes, focus is not restored to the trigger.",
  "repair_strategy": "Add focus management to DialogBase: (1) import isVisible/isDisabled from util, (2) store the triggering element on show(), (3) in _showElement() move focus to [autofocus] or first focusable descendant after a microtask, (4) in _closeAndCleanup() call _onAfterHide() which restores focus to the stored trigger if still visible and enabled.",
  "edits": [
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "import BaseComponent from './base-component.js'
import Data from './dom/data.js'
import EventHandler, { type BootstrapEvent } from './dom/event-handler.js'
import SelectorEngine from './dom/selector-engine.js'",
      "after": "import BaseComponent from './base-component.js'
import Data from './dom/data.js'
import EventHandler, { type BootstrapEvent } from './dom/event-handler.js'
import SelectorEngine from './dom/selector-engine.js'
import { isDisabled, isVisible } from './util/index.js'"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected declare _element: HTMLDialogElement
  protected declare _config: DialogBaseConfig
  protected declare _isTransitioning: boolean
  protected declare _openedAsModal: boolean
  protected declare _cancelHandler: (event: BootstrapEvent) => void",
      "after": "  protected declare _element: HTMLDialogElement
  protected declare _config: DialogBaseConfig
  protected declare _isTransitioning: boolean
  protected declare _openedAsModal: boolean
  protected declare _cancelHandler: (event: BootstrapEvent) => void
  protected declare _lastFocusedTrigger: HTMLElement | null"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  constructor(element?: string | Element | null, config?: Partial<DialogBaseConfig> | null) {
    super(element, config)

    this._isTransitioning = false
    this._openedAsModal = false
    this._addDialogListeners()
  }",
      "after": "  constructor(element?: string | Element | null, config?: Partial<DialogBaseConfig> | null) {
    super(element, config)

    this._isTransitioning = false
    this._openedAsModal = false
    this._lastFocusedTrigger = null
    this._addDialogListeners()
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  async show(relatedTarget?: HTMLElement): Promise<void> {
    if (!this._canShow(relatedTarget)) {
      return
    }

    await this._show(relatedTarget)
  }",
      "after": "  async show(relatedTarget?: HTMLElement): Promise<void> {
    if (!this._canShow(relatedTarget)) {
      return
    }
    this._lastFocusedTrigger = relatedTarget ?? null
    await this._show(relatedTarget)
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }",
      "after": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      // Lock scroll on the root element (not <body>) so it lands on the same
      // element that carries `scrollbar-gutter: stable`. Co-locating them keeps
      // the gutter reserved while the scrollbar is hidden, so the page doesn't
      // shift (and the ::backdrop covers the gutter instead of leaving a strip).
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }

    // Move focus to the first focusable element inside the dialog
    Promise.resolve().then(() => {
      const autofocus = this._element.querySelector('[autofocus]')
      if (autofocus) {
        autofocus.focus({ preventScroll: true })
        return
      }
      const focusableSelectors = [
        'a[href]',
        'area[href]',
        'input:not([disabled]):not([type="hidden"])',
        'select:not([disabled])',
        'textarea:not([disabled])',
        'button:not([disabled])',
        'iframe',
        'object',
        'embed',
        '[tabindex]:not([tabindex="-1"])',
        '[contenteditable]'
      ].join(',')
      const focusable = this._element.querySelectorAll(focusableSelectors)
      for (const el of focusable) {
        if (isVisible(el) && !isDisabled(el as HTMLElement)) {
          (el as HTMLElement).focus({ preventScroll: true })
          break
        }
      }
    })
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _closeAndCleanup(): void {
    this._element.close()
    this._openedAsModal = false

    // Only restore scroll if no other modal dialogs are open
    if (!document.querySelector('dialog[open]:modal')) {
      document.documentElement.classList.remove(CLASS_NAME_OPEN)
    }
  }",
      "after": "  protected _closeAndCleanup(): void {
    this._element.close()
    this._openedAsModal = false

    // Only restore scroll if no other modal dialogs are open
    if (!document.querySelector('dialog[open]:modal')) {
      document.documentElement.classList.remove(CLASS_NAME_OPEN)
    }

    this._onAfterHide()
  }"
    },
    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _onAfterHide(): void {
    // No-op by default — Dialog overrides to remove nonmodal class
  }",
      "after": "  protected _onAfterHide(): void {
    if (this._lastFocusedTrigger) {
      const trigger = this._lastFocusedTrigger
      this._lastFocusedTrigger = null
      if (isVisible(trigger) && !isDisabled(trigger)) {
        trigger.focus({ preventScroll: true })
      }
    }
    // No-op by default — Dialog overrides to remove nonmodal class
  }"
    }
  ],
  "expected_accessibility_effect": "Opening a drawer moves focus into it, allowing keyboard users to tab through controls; closing returns focus to the trigger, preserving logical tab order.",
  "functional_risks": [
    "Potential focus stealing if the stored trigger is disabled or removed (mitigated by checking visibility and disabled state before restoring focus).",
    "Focusing non-focusable elements could cause issues (limited to standard focusable selectors).",
    "Microtask delay for focus might cause brief focus flash on trigger (acceptable)."
  ],
  "verification_requirements": [
    "After activating sort-open with Enter, focus should be on sort-close.",
    "After activating filters-open with Enter, focus should be on filters-search (due to autofocus).",
    "Pressing Escape in either drawer should return focus to the respective opener button.",
    "Tab navigation within drawer should cycle through its focusable elements.",
    "Activating Apply button after checking In stock should update applied output to "in"."
  ]
}
